			if search.Text ~= query then self:SetQuery(C.truncate(search.Text, 256)) end
		end) end
		self._render()
		return self
	end
	return M
end
end)()

-- keyvalue
__UI_MODULES["keyvalue"] = (function()
-- Structured readouts wrap into stacked key/value rows on narrow screens.
-- Updating one value preserves order and never gives scripts layout ownership.
return function(env)
	local C = env.require("core")
	local M = {}
	function M.KeyValue(section, options)
		local self = env.require("controls").base(section, "KeyValue", options, "stack")
		self.Persist = options.Persist == true
		self._normalize = function(items)
			assert(type(items) == "table" and #items <= 64, "KeyValue expects at most 64 rows")
			local normalized, seen = {}, {}
			for index, item in ipairs(items) do
				assert(type(item) == "table" and type(item.Key) == "string" and #item.Key > 0 and #item.Key <= 128, "KeyValue rows need a bounded Key")
				assert(not seen[item.Key], "Duplicate KeyValue key: " .. item.Key)
				assert(type(item.Value) == "string" or type(item.Value) == "boolean" or C.finite(item.Value), "KeyValue Value must be text, a number or a boolean")
				assert(#tostring(item.Value) <= 4096, "KeyValue Value is too long")
				seen[item.Key] = true
				normalized[index] = { Key = item.Key, Value = tostring(item.Value) }
			end
			for key in pairs(items) do assert(type(key) == "number" and key >= 1 and key <= #items and key == math.floor(key), "KeyValue rows must be an array") end
			assert(#normalized == #items, "KeyValue rows must be a dense array")
			return normalized
		end
		self._value = self._normalize(options.Default or options.Items or {})
		local rows, rowScope = {}, nil
		self._slotHeight = function(width)
			local top, stacked = 0, width < 260 * self._window.TextScale
			for _, row in ipairs(rows) do
				local keyWidth = stacked and width or math.max(1, width * 0.38 - 12)
				local valueWidth = stacked and width or math.max(1, width * 0.62)
				local keyHeight = C.measure(row.key.Text, row.key.TextSize, keyWidth, row.key.Font)
				local valueHeight = C.measure(row.value.Text, row.value.TextSize, valueWidth, row.value.Font)
				row.key.Position, row.key.Size = UDim2.fromOffset(0, top), UDim2.fromOffset(keyWidth, keyHeight)
				row.value.Position = UDim2.fromOffset(stacked and 0 or width * 0.38, top + (stacked and keyHeight + 3 or 0))
				row.value.Size = UDim2.fromOffset(valueWidth, valueHeight)
				top = top + (stacked and keyHeight + valueHeight + 3 or math.max(keyHeight, valueHeight)) + 12
			end
			return math.max(1, top - 12)
		end
		self._render = function()
			if rowScope then rowScope:Destroy() end
			rowScope, rows = C.scope(self._scope), {}
			local owner = { _window = self._window, _scope = rowScope }
			for _, item in ipairs(self._value) do
				local key = C.text(owner, self._slot, item.Key, "Caption", "Muted", { TextYAlignment = Enum.TextYAlignment.Top })
				local value = C.text(owner, self._slot, item.Value, "Body", "Text", { TextYAlignment = Enum.TextYAlignment.Top })
				rowScope:Add(key); rowScope:Add(value)
				rows[#rows + 1] = { key = key, value = value }
			end
			self._layout()
		end
		function self:SetValue(key, value, silent)
			assert(self.Alive, "Control is destroyed")
			local items = self:Get()
			for _, item in ipairs(items) do if item.Key == key then item.Value = value; return self:Set(items, silent) end end
			error("Unknown KeyValue key: " .. tostring(key))
		end
		self._render()
		return self
	end
	return M
end
end)()

-- library
__UI_MODULES["library"] = (function()
return function(env)
	local Window = env.require("window")
	local C, T = env.require("core"), env.require("theme")
	local appearance = env.require("appearance")
	local seasons = env.require("seasons")
	local methods = env.require("config")
	for _, id in ipairs({ "values", "tasks", "profiles" }) do
		for name, method in pairs(env.require(id)) do if name:match("^%u") then methods[name] = method end end
	end
	function methods.GetAppearance(self)
		return { Theme = self._themeName, Accent = self._accent, Colors = C.copy(self._colors or {}),
			CornerRadius = self.CornerRadius or T.Size.Radius, TextScale = self.TextScale, ReducedMotion = self.ReducedMotion,
			Palette = self.Palette, Contrast = self.Contrast, Density = self.Density, Shape = self.Shape,
			Typography = self.Typography, TabHeader = self.TabHeader, SeasonalTheme = self.SeasonalTheme }
	end
	function methods.GetActivePalette(self) return self._activePalette end
	function methods._ScheduleSeasonal(self)
		if self._seasonalCancel then self._seasonalCancel(); self._seasonalCancel = nil end
		if not self.Alive or not self.SeasonalTheme or seasons.manual(self.Palette) or not seasons.current() then return end
		self._seasonalCancel = self._scope:Delay(seasons.nextCheck(), function()
			self._seasonalCancel = nil
			if seasons.palette(self.Palette, self.SeasonalTheme) ~= self._activePalette then self:SetAppearance({})
			else self:_ScheduleSeasonal() end
		end)
	end
	function methods.SetAppearance(self, options)
		assert(self.Alive, "Window is destroyed")
		local value = T.normalizeAppearance(options, self:GetAppearance())
		local activePalette = seasons.palette(value.Palette, value.SeasonalTheme)
		local palette = T.resolve(value.Theme, value.Accent, value.Colors, activePalette, value.Contrast)
		self.Theme, self._themeName, self._accent, self._colors = palette, value.Theme, value.Accent, value.Colors
		self.CornerRadius, self.TextScale = value.CornerRadius, value.TextScale
		self.Palette, self.Contrast, self.Density, self.Shape = value.Palette, value.Contrast, value.Density, value.Shape
		self.Typography, self.TabHeader = value.Typography, value.TabHeader
		self.SeasonalTheme, self._activePalette = value.SeasonalTheme, activePalette
		if options.ReducedMotion ~= nil then self._motionOverride = value.ReducedMotion end
		self.ReducedMotion = value.ReducedMotion
		if self._themeIcon then self._themeIcon(value.Theme == "Light") end
		self:_Refresh()
		self:_Layout()
		self:_Filter()
		if self._appearanceSync then self._appearanceSync() end
		self:_ScheduleSeasonal()
		return self
	end
	function methods.ResetAppearance(self)
		local value = C.copy(self._appearanceDefaults)
		if value.Accent == nil then value.Accent = false end
		self:SetAppearance(value)
		self._motionOverride = self._appearanceMotionOverride
		if self._motionOverride == nil then
			pcall(function() self.ReducedMotion = env.services.GuiService.ReducedMotionEnabled == true end)
			if self._appearanceSync then self._appearanceSync() end
		end
		return self
	end
	function methods.SetTheme(self, name, accent)
		if name == nil then name = "Dark" end
		assert(accent ~= false, "Accent must be a Color3")
		if accent == nil then accent = false end
		return self:SetAppearance({ Theme = name, Accent = accent })
	end
	-- Keep existing setters reflected in the automatic preferences without firing
	-- application callbacks, including changes made by a host script.
