-- profile
__UI_MODULES["profile"] = (function()
-- Local identity belongs to the shared sidebar, not to consumer scripts.
return function(env)
	local C = env.require("core")
	local T = env.require("theme")
	local M = {}
	local placeName, loading, listeners = nil, false, {}
	local function resolvePlace()
		if loading or placeName then return end
		loading = true
		-- Native requests finish naturally; cleanup removes their recipients.
		task.defer(function()
			local ok, result = pcall(function() return env.services.MarketplaceService:GetProductInfo(game.PlaceId) end)
			if ok and type(result) == "table" and type(result.Name) == "string" and result.Name ~= "" then placeName = C.truncate(result.Name, 160) end
			loading = false
			for callback in pairs(listeners) do callback(placeName) end
		end)
	end
	function M.new(window, parent, gameName)
		local self = C.owner(window)
		local player = env.services.Players.LocalPlayer
		local username = player and player.Name or "Local player"
		local displayName = player and player.DisplayName or username
		self.Frame = C.node(self, "Frame", parent, { Name = "Profile", ClipsDescendants = true }, { BackgroundColor3 = "Sidebar" })
		local card = C.node(self, "Frame", self.Frame, { Name = "ProfileCard", Position = UDim2.fromOffset(10, 6), Size = UDim2.new(1, -20, 1, -12) }, { BackgroundColor3 = "Chrome" })
		C.corner(card, 8, self); C.stroke(self, card, "Subtle")
		local avatar = C.node(self, "Frame", self.Frame, { Name = "Avatar", Size = UDim2.fromOffset(T.Size.Avatar, T.Size.Avatar) }, { BackgroundColor3 = "Raised" })
		C.corner(avatar, T.Size.Avatar / 2)
		local initial = C.text(self, avatar, displayName:match("^.[\128-\191]*") or "?", "Heading", "Text", { Name = "Initial", Size = UDim2.fromScale(1, 1), TextXAlignment = Enum.TextXAlignment.Center })
		local photo = C.node(self, "ImageLabel", avatar, { Name = "Headshot", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ScaleType = Enum.ScaleType.Crop })
		C.corner(photo, T.Size.Avatar / 2)
		local function loaded() if self._scope.alive then initial.Visible = photo.IsLoaded ~= true end end
		self._scope:Connect(photo:GetPropertyChangedSignal("IsLoaded"), loaded)
		if player and player.UserId > 0 then
			photo.Image = string.format("rbxthumb://type=AvatarHeadShot&id=%.0f&w=150&h=150", player.UserId)
			task.defer(function()
				if not self._scope.alive then return end
				local ok, image, ready = pcall(function() return env.services.Players:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150) end)
				if not self._scope.alive or not photo.Parent then return end
				if ok and ready and type(image) == "string" then photo.Image = image end
				pcall(function() env.services.ContentProvider:PreloadAsync({ photo }) end)
				loaded()
			end)
		end
		local name = C.text(self, self.Frame, displayName, "Heading", "Text", { Name = "DisplayName", TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
		local account = C.text(self, self.Frame, "@" .. username, "Caption", "Muted", { Name = "Username", TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
		local place = C.text(self, self.Frame, gameName or placeName or "Current experience", "Caption", "Secondary", { Name = "GameName", TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
		local function update(value) if self._scope.alive and value then place.Text = value end end
		if not gameName then listeners[update] = true; self._scope:Add(function() listeners[update] = nil end); resolvePlace() end
		function self.Layout(width)
			local line = math.ceil(18 * window.TextScale)
			local identityHeight = math.max(T.Size.Avatar, line * 2)
			local height = identityHeight + line + 42
			local left = 20 + T.Size.Avatar + 10
			avatar.Position = UDim2.fromOffset(20, 16)
			name.Position, name.Size = UDim2.fromOffset(left, 16), UDim2.fromOffset(math.max(1, width - left - 20), line)
			account.Position, account.Size = UDim2.fromOffset(left, 16 + line), UDim2.fromOffset(math.max(1, width - left - 20), line)
			place.Position, place.Size = UDim2.fromOffset(20, 24 + identityHeight), UDim2.fromOffset(math.max(1, width - 40), line)
			self.Frame.Size = UDim2.fromOffset(width, height)
			return height
		end
		return self
	end
	return M
end
end)()

-- profiles
__UI_MODULES["profiles"] = (function()
return function(env)
	local config = env.require("config")
	local M = {}
	function M.ListConfigs(window)
		if not window.Alive then return false, "Window is destroyed" end
		local list = env.globals.listfiles or listfiles
		local exists = env.globals.isfolder or isfolder
		if type(list) ~= "function" then return false, "This host does not provide listfiles" end
		local ok, result = pcall(function()
			local _, folder = config.pathFor(window, "default")
			if type(exists) == "function" and not exists(folder) then return {} end
			local names, seen = {}, {}
			local entries = list(folder)
			assert(type(entries) == "table", "The host returned an invalid profile listing")
			for _, entry in ipairs(entries) do
				if type(entry) == "string" then
					local normalized = entry:gsub("\\", "/"):gsub("/+", "/"):gsub("^%./", "")
					local name = normalized:match("/([%w_-]+)%.json$") or normalized:match("^([%w_-]+)%.json$")
					if name and #name <= 48 and not seen[name] then
						-- Host listings sometimes return basenames. Accept only files
						-- directly in this window's profile directory, never children.
						local wanted = folder .. "/" .. name .. ".json"
						local absoluteSuffix = normalized:sub(-#wanted - 1) == "/" .. wanted and not normalized:find("/../", 1, true)
						if normalized == wanted or normalized == name .. ".json" or absoluteSuffix then names[#names + 1], seen[name] = name, true end
					end
				end
			end
			table.sort(names)
			return names
		end)
		return ok, result
	end
	function M.DeleteConfig(window, name)
		if not window.Alive then return false, "Window is destroyed" end
		local remove = env.globals.delfile or delfile
		local exists = env.globals.isfile or isfile
		if type(remove) ~= "function" then return false, "This host does not provide delfile" end
		local ok, result = pcall(function()
			local path = config.pathFor(window, name)
			if type(exists) == "function" and not exists(path) then return false end
			remove(path)
			if type(exists) == "function" then assert(not exists(path), "The host did not remove the profile") end
			return true
		end)
		return ok, result
	end
	return M
end
end)()

-- seasons
__UI_MODULES["seasons"] = (function()
-- Read the player's calendar afresh so daylight-saving and clock changes remain
-- local. Hosts without the local-date API retain their selected palette.
return function(env)
	local M = {}
	function M.current()
		local ok, date = pcall(function() return DateTime.now():ToLocalTime() end)
		if ok and type(date) == "table" and type(date.Month) == "number" and type(date.Day) == "number" then return date end
		return nil
	end
	function M.active(date)
		if not date then return nil end
		local month, day = date.Month, date.Day
		if month == 2 and day == 14 then return "Valentine" end
		if month == 4 and day == 22 then return "EarthDay" end
		if month == 6 and day >= 1 and day <= 30 then return "Pride" end
		if month == 9 and day == 21 then return "Peace" end
		if month == 10 and day >= 30 and day <= 31 or month == 11 and day >= 1 and day <= 2 then return "Halloween" end
		if month == 12 and day >= 20 and day <= 26 then return "Christmas" end
		if month == 12 and day == 31 or month == 1 and day >= 1 and day <= 2 then return "NewYear" end
		return nil
	end
	function M.manual(palette)
		return env.require("palettes").isSeasonal(palette)
	end
	function M.palette(palette, enabled)
		if not enabled or M.manual(palette) then return palette end
		return M.active(M.current()) or palette
	end
	function M.nextCheck()
		local date = M.current()
		if date and type(date.Hour) == "number" and type(date.Minute) == "number" and type(date.Second) == "number" then
			local remaining = 86400 - (date.Hour * 3600 + date.Minute * 60 + date.Second)
			return math.max(1, math.min(60, remaining))
		end
		return 60
	end
	return M
end
end)()

-- shape
__UI_MODULES["shape"] = (function()
-- Named shapes offer predictable corners without requiring pixel choices.
-- Explicit CornerRadius remains an optional, bounded advanced preference.
return function(env)
	local M = { Names = { "Rounded", "Soft", "Square" } }
	local radii = { Rounded = 8, Soft = 14, Square = 0 }
	function M.valid(name) return radii[name] ~= nil end
	function M.radius(name)
		local radius = radii[name or "Rounded"]
		assert(radius ~= nil, "Unknown shape: " .. tostring(name))
		return radius
	end
	function M.infer(radius)
		for _, name in ipairs(M.Names) do if radii[name] == radius then return name end end
		return "Custom"
	end
	return M
end
end)()

